import{_ as e,o as a,c as l,a5 as o}from"./chunks/framework.Cooo9kuv.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"831-批量视频分别时长统计并汇总时长工具","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["音频视频批处理"],"标签":["excel导出","批量视频时长统计工具","本地视频统计软件","视频文件管理","视频时长汇总"]},"headers":[{"level":3,"title":"批量视频分别时长统计并汇总时长工具","slug":"批量视频分别时长统计并汇总时长工具","link":"#批量视频分别时长统计并汇总时长工具","children":[]},{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"📑 程序截图","slug":"📑-程序截图","link":"#📑-程序截图","children":[]},{"level":3,"title":"界面介绍","slug":"界面介绍","link":"#界面介绍","children":[]},{"level":3,"title":"基本操作指南","slug":"基本操作指南","link":"#基本操作指南","children":[]},{"level":3,"title":"实际使用场景示例","slug":"实际使用场景示例","link":"#实际使用场景示例","children":[{"level":4,"title":"场景一：统计课程视频总时长","slug":"场景一-统计课程视频总时长","link":"#场景一-统计课程视频总时长","children":[]},{"level":4,"title":"场景二：整理个人视频收藏","slug":"场景二-整理个人视频收藏","link":"#场景二-整理个人视频收藏","children":[]},{"level":4,"title":"场景三：工作视频素材管理","slug":"场景三-工作视频素材管理","link":"#场景三-工作视频素材管理","children":[]}]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"📑 程序使用环境及相关说明","slug":"📑-程序使用环境及相关说明","link":"#📑-程序使用环境及相关说明","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"Q: 工具找不到我的视频文件怎么办？","slug":"q-工具找不到我的视频文件怎么办","link":"#q-工具找不到我的视频文件怎么办","children":[]},{"level":3,"title":"Q: Excel文件中为什么没有某些视频的信息？","slug":"q-excel文件中为什么没有某些视频的信息","link":"#q-excel文件中为什么没有某些视频的信息","children":[]},{"level":3,"title":"Q: 处理过程中断或报错怎么办？","slug":"q-处理过程中断或报错怎么办","link":"#q-处理过程中断或报错怎么办","children":[]},{"level":3,"title":"Q: 统计结果中的时长是否准确？","slug":"q-统计结果中的时长是否准确","link":"#q-统计结果中的时长是否准确","children":[]},{"level":3,"title":"📑 程序使用说明","slug":"📑-程序使用说明","link":"#📑-程序使用说明","children":[]}],"relativePath":"md/音频视频批处理/831-批量视频分别时长统计并汇总时长工具.md","filePath":"md/音频视频批处理/831-批量视频分别时长统计并汇总时长工具.md"}'),n={name:"md/音频视频批处理/831-批量视频分别时长统计并汇总时长工具.md"};function r(p,t,s,i,h,g){return a(),l("div",null,[...t[0]||(t[0]=[o('<h3 id="批量视频分别时长统计并汇总时长工具" tabindex="-1">批量视频分别时长统计并汇总时长工具 <a class="header-anchor" href="#批量视频分别时长统计并汇总时长工具" aria-label="Permalink to &quot;批量视频分别时长统计并汇总时长工具&quot;">​</a></h3><p>用于快速统计多个视频文件时长信息的桌面软件。该工具能够自动扫描指定文件夹中的所有视频文件，获取每个视频的时长，并将统计结果按文件夹组织汇总到Excel文件中。软件支持多种视频格式，可选择穿透子文件夹扫描，还能自定义导出字段，满足不同用户的统计需求。</p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><strong>批量统计</strong>：一次性统计多个视频文件的时长信息</p><p><strong>多格式支持</strong>：支持</p><p>&#39;.mp4&#39;, &#39;.avi&#39;, &#39;.mov&#39;, &#39;.wmv&#39;, &#39;.flv&#39;, &#39;.mkv&#39;, &#39;.mp3&#39;, &#39;.wav&#39;, &#39;.flac&#39;, &#39;.aac&#39;, &#39;.ogg&#39;, &#39;.wma&#39;,&#39;.m4a&#39;</p><p><strong>文件夹分类</strong>：按文件夹自动分类统计结果，便于管理</p><p><strong>穿透子文件夹</strong>：可选择是否扫描所有子文件夹中的视频文件</p><p><strong>自定义字段</strong>：可自定义导出的字段信息，包括文件路径、所在目录和文件名</p><p><strong>详细时长展示</strong>：同时显示格式化时长（小时:分:秒）和各时间单位的具体数值</p><p><strong>总计功能</strong>：自动计算每个文件夹中所有视频的总时长</p><p><strong>无网络使用</strong>：完全本地运行，确保数据安全</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251022200213176113453370904.png" alt=""></p><h3 id="界面介绍" tabindex="-1">界面介绍 <a class="header-anchor" href="#界面介绍" aria-label="Permalink to &quot;界面介绍&quot;">​</a></h3><p>主界面包含以下主要元素：</p><p><strong>选择文件夹</strong>：用于浏览并选择包含视频文件的文件夹</p><p><strong>穿透子文件夹</strong>：勾选后将扫描选定文件夹及其所有子文件夹中的视频文件</p><p><strong>导出字段</strong>：可选择要导出到Excel的字段信息</p><p>文件路径：导出完整的文件路径</p><p>文件所在目录：导出文件所在的目录路径</p><p>文件名：仅导出文件名</p><p><strong>保存Excel</strong>：设置生成的Excel文件的保存位置和文件名</p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><p><strong>选择视频文件夹</strong>：</p><p>点击&quot;浏览&quot;按钮</p><p>在弹出的对话框中选择包含视频文件的文件夹</p><p>点击&quot;确定&quot;按钮</p><p><strong>设置扫描选项</strong>：</p><p>如需扫描子文件夹中的视频，勾选&quot;穿透子文件夹&quot;选项</p><p>根据需要选择要导出的字段信息</p><p><strong>设置Excel保存位置</strong>：</p><p>点击&quot;浏览&quot;按钮</p><p>选择Excel文件的保存位置并输入文件名</p><p>点击&quot;保存&quot;按钮</p><p><strong>开始统计</strong>：</p><p>点击&quot;开始处理&quot;按钮</p><p>观察日志区域，查看处理进度和结果</p><p>处理完成后，日志区域将显示成功信息和保存的Excel文件路径</p><p><strong>查看结果</strong>：</p><p>前往指定的保存位置，打开生成的Excel文件</p><p>Excel文件中按文件夹创建了多个工作表，每个工作表包含相应文件夹中视频文件的时长信息</p><p>每个工作表的末尾都有总计行，显示该文件夹中所有视频的总时长</p><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><h4 id="场景一-统计课程视频总时长" tabindex="-1">场景一：统计课程视频总时长 <a class="header-anchor" href="#场景一-统计课程视频总时长" aria-label="Permalink to &quot;场景一：统计课程视频总时长&quot;">​</a></h4><p><strong>适用人群</strong>：教师、学生</p><p><strong>操作步骤</strong>：</p><p>将课程视频按章节存放在不同的文件夹中</p><p>启动工具，选择课程视频的根文件夹</p><p>勾选&quot;穿透子文件夹&quot;选项，确保能扫描所有章节的视频</p><p>选择保存Excel的位置，文件名设为&quot;课程视频时长统计&quot;</p><p>点击&quot;开始处理&quot;</p><p>处理完成后，Excel文件将按章节显示每个视频的时长和各章节的总时长</p><h4 id="场景二-整理个人视频收藏" tabindex="-1">场景二：整理个人视频收藏 <a class="header-anchor" href="#场景二-整理个人视频收藏" aria-label="Permalink to &quot;场景二：整理个人视频收藏&quot;">​</a></h4><p><strong>适用人群</strong>：视频爱好者</p><p><strong>操作步骤</strong>：</p><p>将不同类型的视频（如电影、纪录片、教程等）存放在各自的文件夹中</p><p>启动工具，选择视频收藏的根文件夹</p><p>勾选&quot;穿透子文件夹&quot;和所有导出字段</p><p>设置Excel保存位置</p><p>开始处理，生成完整的视频时长统计报告</p><p>根据统计结果，可以更好地规划观看时间或管理存储空间</p><h4 id="场景三-工作视频素材管理" tabindex="-1">场景三：工作视频素材管理 <a class="header-anchor" href="#场景三-工作视频素材管理" aria-label="Permalink to &quot;场景三：工作视频素材管理&quot;">​</a></h4><p><strong>适用人群</strong>：视频编辑、内容创作者</p><p><strong>操作步骤</strong>：</p><p>将不同项目的视频素材分别存放在独立文件夹中</p><p>启动工具，选择不勾选&quot;穿透子文件夹&quot;，只统计当前文件夹</p><p>选择需要的导出字段，建议至少勾选&quot;文件名&quot;</p><p>为每个项目单独生成Excel统计文件</p><p>通过统计结果，快速了解各项目素材的总体时长和分布情况</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p><strong>文件格式要求</strong>：确保要统计的文件是支持的视频格式，工具支持的格式包括：MP4、AVI、MOV、WMV、FLV、MKV、MP3、WAV、FLAC、AAC、OGG、WMA、M4A</p><p><strong>处理大型文件夹</strong>：处理包含大量视频文件的文件夹可能需要较长时间，请耐心等待</p><p><strong>权限问题</strong>：确保您有足够的权限访问视频文件和保存Excel的位置</p><p><strong>异常情况</strong>：如果某些视频文件无法获取时长，这些文件将被跳过，不会计入统计结果</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251022200805176113488594892.jpg" alt=""></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251022200837176113491719330.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><h3 id="q-工具找不到我的视频文件怎么办" tabindex="-1">Q: 工具找不到我的视频文件怎么办？ <a class="header-anchor" href="#q-工具找不到我的视频文件怎么办" aria-label="Permalink to &quot;Q: 工具找不到我的视频文件怎么办？&quot;">​</a></h3><p>A：请检查以下几点：1. 确认视频文件格式在支持列表中；2. 确认文件夹路径正确；3. 如需扫描子文件夹，请确保勾选了&quot;穿透子文件夹&quot;选项；4. 检查文件权限是否正确。</p><h3 id="q-excel文件中为什么没有某些视频的信息" tabindex="-1">Q: Excel文件中为什么没有某些视频的信息？ <a class="header-anchor" href="#q-excel文件中为什么没有某些视频的信息" aria-label="Permalink to &quot;Q: Excel文件中为什么没有某些视频的信息？&quot;">​</a></h3><p>A：可能的原因：1. 视频文件格式不支持；2. 视频文件可能已损坏；3. 无法解析该视频文件的时长信息；4. 文件权限不足。</p><h3 id="q-处理过程中断或报错怎么办" tabindex="-1">Q: 处理过程中断或报错怎么办？ <a class="header-anchor" href="#q-处理过程中断或报错怎么办" aria-label="Permalink to &quot;Q: 处理过程中断或报错怎么办？&quot;">​</a></h3><p>A：请查看日志区域的错误信息，根据提示排查问题。</p><h3 id="q-统计结果中的时长是否准确" tabindex="-1">Q: 统计结果中的时长是否准确？ <a class="header-anchor" href="#q-统计结果中的时长是否准确" aria-label="Permalink to &quot;Q: 统计结果中的时长是否准确？&quot;">​</a></h3><p>A：工具使用FFprobe获取视频时长，这是业界标准工具，统计结果通常非常准确。但对于某些特殊编码的视频文件，可能存在微小误差。</p><h3 id="📑-程序使用说明" tabindex="-1">📑 程序使用说明 <a class="header-anchor" href="#📑-程序使用说明" aria-label="Permalink to &quot;📑 程序使用说明&quot;">​</a></h3><p><strong>第一步：先将apitool文件夹复制到C盘根目录下，如下图所示：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251010144245176007856553033-2.jpg" alt=""></p><p><strong>第二步：双击快捷方式使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251022200318176113459823807.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2109.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2109.html</a></p>',98)])])}const d=e(n,[["render",r]]);export{u as __pageData,d as default};
